<ha-icon icon="mdi:moon-waning-crescent"></ha-icon> Mondsmäussion

# Tag {{ tag }}

seit {{ start.day }}. {{ monate[start.month - 1] }} {{ start.year }} · {{ jt.year - start.year }}. Jahrestag in {{ (jt - heute).days }} Tagen

<ha-icon icon="mdi:star-four-points-outline"></ha-icon> {{ states('sensor.mondsmaussion_besonderheiten') }}
</center>
